WITH filtered_transactions AS (SELECT *, CAST(txn_time AS DATE) txn_time_day FROM transactions WHERE merchant IN ('Grab', 'Starbucks', 'Amazon')), agg AS (SELECT TO_DATE(txn_time) txn_day, SUM(amount) total_amount, ROUND((100 * SUM(CASE WHEN txn_type = 'FEE' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_fee FROM filtered_transactions GROUP BY TO_DATE(txn_time)) SELECT txn_day, total_amount, pct_fee FROM agg WHERE total_amount < 11000;
